package com.djibtout.backend.controller;
import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?> validation(MethodArgumentNotValidException e){Map<String,String> fields=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->fields.putIfAbsent(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(body(400,"VALIDATION_ERROR","Données invalides.",fields));}@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<?> badRequest(IllegalArgumentException e){return ResponseEntity.badRequest().body(body(400,"BAD_REQUEST",e.getMessage(),null));}private Map<String,Object> body(int status,String code,String message,Object details){Map<String,Object> value=new LinkedHashMap<>();value.put("timestamp",Instant.now());value.put("status",status);value.put("code",code);value.put("message",message==null?"Erreur de requête.":message);if(details!=null)value.put("details",details);return value;}}
